package com.campusos.backend.controller; import com.campusos.backend.entity.FacultyAssignment; import com.campusos.backend.service.FacultyAssignmentService; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import java.util.List;
@RestController @RequestMapping("/api/faculty-assignments") public class FacultyAssignmentController { private final FacultyAssignmentService s; public FacultyAssignmentController(FacultyAssignmentService s){this.s=s;} @PostMapping public FacultyAssignment create(@RequestBody FacultyAssignment a,@AuthenticationPrincipal String email){return s.createAssignment(a,email);} @GetMapping public List<FacultyAssignment> all(@AuthenticationPrincipal String email){return s.getAllAssignments(email);} @GetMapping("/mine") public List<FacultyAssignment> mine(@AuthenticationPrincipal String email){return s.getMyAssignments(email);} @PutMapping("/{id}") public FacultyAssignment update(@PathVariable Long id,@RequestBody FacultyAssignment a,@AuthenticationPrincipal String email){return s.updateAssignment(id,a,email);} @DeleteMapping("/{id}") public String delete(@PathVariable Long id,@AuthenticationPrincipal String email){s.deleteAssignment(id,email);return "Assignment deleted";} }
